from lib import *
S = SS('k15')
F1 = [['kube-controller-manager', 'Lease 每 2.0 秒续约'], ['kube-scheduler', 'Lease 每 2.0 秒续约'], ['leaseDuration', '15 秒']]
F2 = [['sched-a', 'leader'], ['sched-b', '候选'], ['sched-c', '候选'], ['Lease k15/k15-sched', 'holder = sched-a']]
F3 = [['kill -9', '16.6 秒'], ['force delete', '2.5 秒(租约已释放)'], ['delete', '1.1 秒(租约已释放)']]
F4 = [['Lease 被改成 intruder', ''], ['sched-c 续约失败', 'Leaderelection lost'], ['容器重启', '12.9 秒后'], ['sched-b 接手', '19.1 秒后']]
PANELS = [('f', 'flow', '选主'), ('t', 'term', '实测输出'), ('b', 'bars', '接手耗时(秒)'), ('kv', 'kv', '要点')]
steps = [
    step("kube-system 里 kube-controller-manager 和 kube-scheduler 各有一个 Lease:leaseDurationSeconds=15,leaseTransitions=0;9 秒内分别观察到 6 次、5 次续约,相邻两次 renewTime 的间隔全是 2.0 秒。", f=fl(F1, cur=[0, 1], mark=[2]), t=tl(S(1), mark=lidx(S(1), 'kube-controller-manager:', 'kube-scheduler:')), kv=KV([['holderIdentity', '主机名_随机 uuid'], ['续约间隔', '2.0 秒(retryPeriod)'], ['leaseDurationSeconds', '15 秒内没续约才算过期']], ['续约间隔'])),
    step("自己再跑三个 kube-scheduler 候选者(只用 Lease k15/k15-sched 选主、调度器名 k15-scheduler):sched-a 先启动,日志 Attempting to acquire leader lease… → Successfully acquired lease;sched-b、sched-c 日志里只有 Attempting to acquire leader lease…,一直没有 Successfully。Lease 的 holderIdentity=sched-a_…,leaseTransitions=0。", f=dict(fl(F2, cur=[0, 3]), dim=[1, 2]), t=tl(S(2), mark=lidx(S(2), 'Successfully acquired lease', 'holderIdentity=sched-a'), done=lidx(S(2), 'sched-b 的日志', 'sched-c 的日志')), kv=KV([['同一时刻', '只有一个 holder'], ['落选的', '不停地重试获取锁'], ['选主的“锁”', '就是 API 里的一个 Lease 对象']], ['同一时刻'])),
    step("三种方式让 leader 消失:① 在节点上对 leader 进程 kill -9——Lease 没有释放,16.6 秒后 sched-b 接手(leaseTransitions 0→1);② kubectl delete pod --grace-period=0 --force——Lease 先变成 holder=(空)、leaseDuration=1(进程退出前释放了租约),2.5 秒后 sched-a 接手;③ 普通 kubectl delete pod(SIGTERM)——同样先释放,1.1 秒后 sched-c 接手。", f=fl(F3, cur=[0], done=[1, 2]), t=tl(S(3), mark=lidx(S(3), '16.6 秒', '② kubectl delete', '③ kubectl delete'), done=lidx(S(3), 'leaseDuration=1')), b=bars([['kill -9(没释放)', 16.6, '16.6 s'], ['force delete(释放)', 2.5, '2.5 s'], ['delete SIGTERM(释放)', 1.1, '1.1 s']], 16.6, mark=[0], done=[1, 2]), kv=KV([['没来得及释放', '要等 leaseDuration 过期:约 15 秒 + 重试间隔'], ['有机会释放', '1~3 秒就能换人'], ['--force --grace-period=0', 'API 对象立刻没了,进程仍会先收到终止信号']], ['没来得及释放'])),
    step("把 Lease 的 holderIdentity 改成 intruder(当前 leader 是 sched-c):sched-c 续约不上,日志 Failed to renew lease … context deadline exceeded → Leaderelection lost,进程退出,12.9 秒后容器重启(0→1)。intruder 一直占着 Lease,直到从改写起 19.1 秒后 sched-b 接手,leaseTransitions=4。", f=fl(F4, cur=[1], mark=[0, 3], done=[2]), t=tl(S(4), mark=lidx(S(4), 'Leaderelection lost', 'Failed to renew lease'), done=lidx(S(4), 'intruder 一直占着')), kv=KV([['续约失败', '超过 renewDeadline 就主动退出'], ['不再是 leader', '进程直接退出,而不是继续干活'], ['新 leader', '要自己观察满一个 leaseDuration 才能抢']], ['续约失败'])),
]
A = mkartk('k15', 15, 'Kubernetes,Leader election,Lease,kube-scheduler,选主,故障转移,真实验证,动画演示',
    '在 kind 集群里实测 Kubernetes 的 Lease 选主:kube-controller-manager 与 kube-scheduler 的 Lease 每 2.0 秒续约、leaseDurationSeconds=15;自己跑三个 kube-scheduler 候选者争同一个 Lease,只有一个 Successfully acquired lease;kill -9 leader 要 16.6 秒才换人,而 SIGTERM 或 force delete 会先释放租约,1.1~2.5 秒就换人;Lease 被改写后原 leader 报 Leaderelection lost 并退出,新 leader 在 19.1 秒后接手。',
    '多副本的控制器怎么保证同一时刻只有一个在干活?答案是一个叫 Lease 的 API 对象。这篇不看文档,直接让三个真实的 kube-scheduler 争一把锁,然后用 kill -9、force delete、普通删除和篡改 Lease 四种方式弄掉 leader,量出每种情况下换人要多久、Lease 里发生了什么。',
    [('2.0 秒', 'kube-controller-manager 与 kube-scheduler 的 Lease 相邻两次续约的间隔'), ('16.6 秒 vs 1.1 秒', 'kill -9 leader(租约没释放)与普通删除(租约被释放)后新 leader 接手所花的时间'), ('Leaderelection lost', '当前 leader 发现 Lease 被别人改写、续约失败之后的日志')],
    [('Lease 里写了什么', '<p>选主用的“锁”是 <code>coordination.k8s.io</code> 里的 <code>Lease</code> 对象:<code>holderIdentity</code>(主机名加随机 uuid)是当前持有者,<code>renewTime</code> 是它最后一次续约,<code>leaseDurationSeconds</code> 是别人要等多久才能抢,<code>leaseTransitions</code> 记录换过几次主。实测 kube-controller-manager 和 kube-scheduler 的 Lease 每 2.0 秒续约一次,<code>leaseDurationSeconds=15</code>。</p>'),
     ('三个候选者', '<p>用同样的 kube-scheduler 镜像再起三个副本(自定义调度器名 <code>k15-scheduler</code> 与 Lease <code>k15/k15-sched</code>,不影响默认调度器)。先启动的 sched-a 日志里 <code>Attempting to acquire leader lease…</code> 后紧跟 <code>Successfully acquired lease</code>;sched-b、sched-c 只有前一句,一直在重试。选主就是抢一个对象的 <code>holderIdentity</code>,抢到的人负责续约。</p>'),
     ('换人要多久', '<p>三种让 leader 消失的方式差别很大。在节点上对进程 <code>kill -9</code>,它没机会释放租约,sched-b 要等租约过期:16.6 秒。<code>kubectl delete pod --grace-period=0 --force</code> 只是让 API 对象立刻消失,kubelet 仍会终止进程,进程退出前把 Lease 置成 <code>holderIdentity</code> 为空、<code>leaseDurationSeconds=1</code>(释放),别的候选者 2.5 秒就接手;普通删除(SIGTERM)同样释放,1.1 秒接手。所以“滚动升级时 leader 切换很快、节点突然掉电时要十几秒”是正常现象。</p>'),
     ('Lease 被改写', '<p>把 <code>holderIdentity</code> 改成 <code>intruder</code> 后,当前 leader sched-c 的续约失败(<code>Failed to renew lease … context deadline exceeded</code>),随即 <code>Leaderelection lost</code>、进程退出,容器 12.9 秒后重启——leader 一旦发现自己不再持有锁就停止工作,而不是继续。新 leader 是 sched-b,在改写之后 19.1 秒才接手:它必须自己观察满一个 <code>leaseDuration</code>(15 秒)没有变化才敢抢,用的是自己本地的时钟,而不是 <code>renewTime</code> 里的时间戳。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);候选者是三个裸 Pod(sched-a/b/c),运行 registry.k8s.io/kube-scheduler:v1.37.0(节点镜像自带),配置文件设 leaderElection(leaseDuration 15s、renewDeadline 10s、retryPeriod 2s、resourceLock leases、命名空间 k15、名字 k15-sched)和 schedulerName k15-scheduler,用独立的 ServiceAccount 与 RBAC;kill -9 通过 docker exec 进节点用 crictl inspect 找到进程 pid 后 kill -9;Lease 状态用每 50 毫秒读取一次的结果记录变化;每种情形各一次,接手时间每次运行不同',
     '没有验证:真正的控制面多副本(kind 本次是单控制面);client-go 的 leaderelection 在时钟漂移下的行为;resourceLock 为 configmaps/endpoints 的旧实现;Lease 的 holderIdentity 被改写时 leader 的精确判定逻辑(只观察到了续约失败后退出);LeaderElectionCoordinated(协调式选主,Kubernetes 较新的特性);大量 Lease 对 etcd 的写入压力'],
    'Lease 选主', PANELS)
